#!/usr/bin/env python3
r"""Adds SAM 3.1 (Meta Responses API) support to GreenWatch AI.

Usage (PowerShell, from anywhere):
    python apply_sam_fix.py C:\Users\Melody\Desktop\greenwatch-ai
Then:
    cd C:\Users\Melody\Desktop\greenwatch-ai\backend
    pip install -r requirements-dev.txt
    python -m pytest -q

What it does (idempotent; it changes nothing if any expected text is not found):
  NEW   backend/app/services/sam_responses.py    streamed /responses client + Meta's parser + mask placement
  NEW   backend/tests/test_sam_responses.py      tests using Meta's own mask encoder
  EDIT  backend/app/services/meta_client.py      segment(): use the new path when META_SEGMENT_PATH=responses
  EDIT  backend/requirements.txt                 + meta-sam-parser
  EDIT  scripts/gate0.py                         probe/run understand /responses mode
  EDIT  backend/.env.example                     documents the settings
"""
import base64
import pathlib
import sys

MODULE_B64 = ""
TESTS_B64 = ""

PROBE_FN = '''def probe_responses(s, client, png: bytes, prompt: str) -> int:
    """Probe for SAM 3.1 over POST /responses (streamed, token masks decoded with meta-sam-parser)."""
    from app.services import sam_responses

    res = sam_responses.segment_detailed(s, client._headers(), png, prompt)  # noqa: SLF001
    (OUT / "probe_raw_output.txt").write_text(res.raw_text[:2_000_000])
    banner(f"SAM 3.1 via /responses ({res.seconds:.2f}s) -> gate0_out/probe_raw_output.txt")
    sent = Image.open(io.BytesIO(png)).size
    print("raw output, first 300 chars:", res.raw_text.strip().replace("\\n", " ")[:300])
    print(f"objects: {len(res.objects)}   frame size reported by API: {res.frame_size_reported}   sent: {sent}")
    for o in res.objects[:20]:
        print("  ", o)
    for w in res.warnings:
        print("WARNING:", w)
    if not res.masks:
        print("The API completed with an EMPTY result: nothing matched this prompt on this image. "
              "The format is fine; try another prompt or a different image.")
        return 1
    rgb = np.asarray(Image.open(io.BytesIO(png)).convert("RGB"))
    union = np.zeros(rgb.shape[:2], dtype=bool)
    for m in res.masks:
        union |= m
    cat = prompt if prompt in ("buildings", "trees", "vegetation") else "vegetation"
    (OUT / "probe_overlay.png").write_bytes(make_overlay(rgb, union, cat))
    print(f"{len(res.masks)} instance(s); union covers {union.mean():.2%} of the image. Look at gate0_out/probe_overlay.png.")
    print("FORMAT OK: SAM output parses and decodes. META_SEGMENT_BODY / META_SEGMENT_MASKS_PATH are not used in this mode.")
    return 0


'''

ENV_APPEND = """
# ---- SAM 3.1 over the Responses API (documented at https://dev.meta.ai/docs/sam/segmenting) ----
# Set META_SEGMENT_PATH=responses to use it. META_SEGMENT_BODY and META_SEGMENT_MASKS_PATH are then ignored.
#   META_BASE_URL=https://api.meta.ai/v1
#   META_SEGMENT_PATH=responses
#   SAM_MODEL=sam-3.1
#   AGENT_MODEL=muse-spark-1.3
# Optional: META_SAM_MASK_ENCODING=one_bit (default) | lossless | (empty = omit)
"""

# (relative path, old text, new text); old text is matched with LF newlines.
EDITS = [
    ("backend/app/services/meta_client.py",
     "        s = self.s\n        if not (s.meta_segment_path and s.meta_segment_body and s.meta_segment_masks_path):\n",
     "        s = self.s\n"
     "        from app.services import sam_responses  # SAM 3.1 over POST /responses (streamed, token masks)\n\n"
     "        if sam_responses.is_responses_path(s.meta_segment_path):\n"
     "            return sam_responses.segment(s, self._headers(), image_png, prompt)\n"
     "        if not (s.meta_segment_path and s.meta_segment_body and s.meta_segment_masks_path):\n"),
    ("scripts/gate0.py",
     "def cmd_probe(args: argparse.Namespace) -> int:\n",
     PROBE_FN + "def cmd_probe(args: argparse.Namespace) -> int:\n"),
    ("scripts/gate0.py",
     "    client = HttpMetaClient(s)\n    body = segment_body(s, png, args.prompt)\n",
     "    client = HttpMetaClient(s)\n"
     "    from app.services import sam_responses\n\n"
     "    if sam_responses.is_responses_path(s.meta_segment_path):\n"
     "        return probe_responses(s, client, png, args.prompt)\n"
     "    body = segment_body(s, png, args.prompt)\n"),
    ("scripts/gate0.py",
     "    missing = [k for k, v in required.items() if not v]\n",
     "    from app.services import sam_responses\n\n"
     "    if sam_responses.is_responses_path(s.meta_segment_path):\n"
     "        required.pop(\"META_SEGMENT_MASKS_PATH\")  # not used in /responses mode\n"
     "    missing = [k for k, v in required.items() if not v]\n"),
]


def read(path):
    text = path.read_bytes().decode("utf-8")
    return text.replace("\r\n", "\n"), "\r\n" in text


def write(path, text, crlf):
    path.write_bytes((text.replace("\n", "\r\n") if crlf else text).encode("utf-8"))


def main():
    root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
    if not (root / "backend/app/services/meta_client.py").exists() or not (root / "scripts/gate0.py").exists():
        sys.exit(f"{root} does not look like the greenwatch-ai repo (backend/app/services/meta_client.py not found).")

    # Dry run: every edit must match before anything is written.
    plan = []
    for rel, old, new in EDITS:
        p = root / rel
        text, _ = read(p)
        if new in text:
            plan.append((rel, None, old, new))
        elif text.count(old) == 1:
            plan.append((rel, p, old, new))
        else:
            sys.exit(f"STOPPED, nothing changed: expected text not found exactly once in {rel}. "
                     "Your copy differs from the one this script was written for; send me that file.")

    for rel, p, old, new in plan:
        if p is None:
            print(f"skip (already applied): {rel}")
            continue
        text, crlf = read(p)
        write(p, text.replace(old, new, 1), crlf)
        print(f"edited: {rel}")

    req = root / "backend/requirements.txt"
    text, crlf = read(req)
    if "meta-sam-parser" not in text:
        write(req, text.rstrip("\n") + "\nmeta-sam-parser>=0.1.0\n", crlf)
        print("edited: backend/requirements.txt")

    env = root / "backend/.env.example"
    if env.exists():
        text, crlf = read(env)
        if "SAM 3.1 over the Responses API" not in text:
            write(env, text.rstrip("\n") + "\n" + ENV_APPEND, crlf)
            print("edited: backend/.env.example")

    (root / "backend/app/services/sam_responses.py").write_bytes(base64.b64decode(MODULE_B64))
    (root / "backend/tests/test_sam_responses.py").write_bytes(base64.b64decode(TESTS_B64))
    print("wrote: backend/app/services/sam_responses.py, backend/tests/test_sam_responses.py")
    print("\nDone. Next: cd backend; pip install -r requirements-dev.txt; python -m pytest -q")


main()